def sync_webp_paths(apps, schema_editor):
    static_root_src = os.path.join(settings.BASE_DIR, 'static')
    media_root = str(settings.MEDIA_ROOT)

    def _to_webp_if_exists(rel_path, base_dir):
        if not rel_path:
            return rel_path
        lower = rel_path.lower()
        if not lower.endswith(('.jpg', '.jpeg', '.png')):
            return rel_path
        candidate = os.path.splitext(rel_path)[0] + '.webp'
        if os.path.exists(os.path.join(base_dir, candidate.lstrip('/'))):
            return candidate
        return rel_path

